 let data=$state<(Summary&{recent:Detection[]})|null>(null),activity=$state<{date:string;count:number}[]>([]),error=$state('');
 async function load(){error='';try{[data,activity]=await Promise.all([api('/dashboard/overview'),api('/analytics/activity?days=7')]);}catch(e){error=(e as Error).message;}}
 $effect(()=>{if($user)load();});
</script>
<Protected><div class="page-title"><div><h1>Overview</h1><p>Your world, a little better understood.</p></div><a class="btn" href="/detect/live"><Video size={16}/>New detection <ArrowUpRight size={15}/></a></div>{#if error}<div class="notice error" role="alert">{error}<button onclick={load}>Retry</button></div>{:else if data}<Metrics {data}/><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Detection activity</h2><span>Last 7 days · UTC</span></div><Activity data={activity}/></section><section class="panel quick-actions"><div class="panel-heading"><h2>A fresh perspective</h2><Scan size={18}/></div><a href="/detect/live"><Video size={22}/><div><strong>See it live</strong><p>Explore with your camera.</p></div><ArrowUpRight size={18}/></a><a href="/detect/image"><Image size={22}/><div><strong>Look closer</strong><p>Find objects in an image.</p></div><ArrowUpRight size={18}/></a></section></div><section class="recent-section"><div class="section-title"><h2>Recent detections</h2><a href="/history">View all history <ArrowRight size={15}/></a></div>{#if data.recent.length}<div class="history-grid">{#each data.recent as d}<a class="history-card" href={`/history/${d.id}`}><img src={d.image_url} alt="Saved detection"/><div><span>{d.source_type==='camera'?'Live camera':'Image upload'} · {new Date(d.detected_at).toLocaleDateString()}</span><strong>{d.total_objects} objects detected <ArrowUpRight size={16}/></strong><small>{[...new Set(d.objects.map(o=>o.object_name))].join(', ')||'No objects'}</small></div></a>{/each}</div>{:else}<div class="empty-history"><History size={30} strokeWidth={1.2}/><div><h3>Your discoveries start here.</h3><p>Save your first snapshot to build a picture of what you see.</p></div><a href="/detect/image" class="btn outline">Analyze an image <ArrowUpRight size={16}/></a></div>{/if}</section>{:else}<div class="loading-state">Loading your overview…</div>{/if}</Protected>
